package com.example.expenses.rates;

import java.math.BigDecimal;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientException;

@Component
public class RestExchangeRateProvider implements ExchangeRateProvider {

    private final RestClient client;

    public RestExchangeRateProvider(RestClient.Builder builder,
                                    @Value("${exchange-rates.base-url}") String baseUrl) {
        this.client = builder.baseUrl(baseUrl).build();
    }

    record RateResponse(BigDecimal rate) {}

    @Override
    public BigDecimal rateToEur(String currency) {
        if ("EUR".equals(currency)) {
            return BigDecimal.ONE;
        }
        try {
            RateResponse body = client.get().uri("/rates/{currency}", currency)
                    .retrieve().body(RateResponse.class);
            if (body == null || body.rate() == null || body.rate().signum() <= 0) {
                throw new RateUnavailableException("Invalid rate for " + currency, null);
            }
            return body.rate();
        } catch (RestClientException e) {
            throw new RateUnavailableException("Rate unavailable for " + currency, e);
        }
    }
}
