package com.example.expenses.claims;

import com.example.expenses.rates.ExchangeRateProvider;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.UUID;
import org.springframework.stereotype.Service;

@Service
public class ClaimService {

    static final BigDecimal APPROVAL_THRESHOLD_EUR = new BigDecimal("1000");

    private final ExchangeRateProvider rates;
    private final ClaimRepository repository;

    public ClaimService(ExchangeRateProvider rates, ClaimRepository repository) {
        this.rates = rates;
        this.repository = repository;
    }

    public Claim submit(ClaimRequest request) {
        BigDecimal amountEur = request.amount()
                .multiply(rates.rateToEur(request.currency()))
                .setScale(2, RoundingMode.HALF_UP);
        ClaimStatus status = amountEur.compareTo(APPROVAL_THRESHOLD_EUR) > 0
                ? ClaimStatus.PENDING_APPROVAL : ClaimStatus.APPROVED;
        return repository.save(new Claim(UUID.randomUUID(), request.employeeId(),
                request.amount(), request.currency(), amountEur, status));
    }
}
